// AI-assisted implementation: OpenAI Codex. Supplied recordings are not generated by this code.
using UnityEngine;

namespace TitanGate.Game
{
    /// <summary>Two-source, unscaled crossfades for the user's chapter music. Does not alter SFX.</summary>
    public sealed class StageMusicPlayer : MonoBehaviour
    {
        public enum Cue { None, Opening, Ship, Mars, Ending }
        public Cue CurrentCue { get; private set; }
        public bool HasOverride => CurrentCue != Cue.None && _current >= 0;
        public AudioSource CurrentSource => _current >= 0 ? _sources[_current] : null;

        readonly AudioSource[] _sources = new AudioSource[2];
        readonly float[] _gain = new float[2];
        int _current = -1;
        float _duckUntil, _duckGain = 1f;
        const float FadeSeconds = 1.2f;
        const float MusicGain = 0.72f;

        void Awake()
        {
            for (int i = 0; i < _sources.Length; i++)
            {
                var child = new GameObject("Chapter music " + i);
                child.transform.SetParent(transform, false);
                var source = child.AddComponent<AudioSource>();
                source.playOnAwake = false;
                source.spatialBlend = 0f;
                source.volume = 0f;
                source.pitch = 1f;
                _sources[i] = source;
            }
            Settings.Changed += ApplyVolumes;
        }

        void OnDestroy() => Settings.Changed -= ApplyVolumes;

        /// <summary>Briefly leave room for collection/completion feedback, then recover smoothly.</summary>
        public void DuckFor(float seconds) => _duckUntil = Mathf.Max(_duckUntil, Time.unscaledTime + seconds);

        public bool Play(Cue cue)
        {
            if (cue == Cue.None) { Stop(); return false; }
            // Repeated state refreshes, skipped cutscenes and Continue must not restart a song.
            if (cue == CurrentCue && CurrentSource != null && CurrentSource.clip != null) return true;
            string file = cue == Cue.Opening ? "opening" : cue == Cue.Ship ? "ship" : cue == Cue.Mars ? "mars" : "ending";
            var clip = Resources.Load<AudioClip>("Audio/UserScore/" + file);
            if (clip == null)
            {
                Debug.LogWarning("Chapter music missing: " + file + "; keeping the existing soundtrack available.");
                Stop();
                return false;
            }

            int next = _current == 0 ? 1 : 0;
            var source = _sources[next];
            source.Stop();
            _gain[next] = 0f;
            source.volume = 0f;
            source.clip = clip;
            source.loop = cue != Cue.Ending;
            source.Play();
            _current = next;
            CurrentCue = cue;
            Debug.Log("Chapter music: " + cue + " / " + file);
            return true;
        }

        public void Stop()
        {
            CurrentCue = Cue.None;
            _current = -1;
        }

        void Update()
        {
            float target = Time.unscaledTime < _duckUntil ? .42f : 1f;
            _duckGain = Mathf.MoveTowards(_duckGain, target, Time.unscaledDeltaTime / (target < _duckGain ? .06f : .45f));
            float step = Time.unscaledDeltaTime / FadeSeconds;
            for (int i = 0; i < _sources.Length; i++)
            {
                _gain[i] = Mathf.MoveTowards(_gain[i], i == _current ? 1f : 0f, step);
                if (i != _current && _gain[i] <= 0f && _sources[i].isPlaying) _sources[i].Stop();
            }
            ApplyVolumes();
        }

        void ApplyVolumes()
        {
            float volume = Settings.Master * Settings.Ambience * MusicGain * _duckGain;
            for (int i = 0; i < _sources.Length; i++)
                if (_sources[i] != null) _sources[i].volume = _gain[i] * volume;
        }
    }
}
